def two_sum_brute(nums: list[int], target: int):
    checks = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            checks += 1
            if nums[i] + nums[j] == target:
                return (i, j), checks
    return None, checks

print(two_sum_brute([2, 7, 11, 15], 9))
print(two_sum_brute(list(range(1_000)), 1_997))

