def pair(result):
    return None if result is None else tuple(result)

assert pair(two_sum([2, 7, 11, 15], 9)) == (0, 1), "two_sum([2, 7, 11, 15], 9) should be (0, 1)."
assert pair(two_sum([3, 2, 4], 6)) == (1, 2), "two_sum([3, 2, 4], 6) should be (1, 2): don't use the same element twice."
assert pair(two_sum([3, 3], 6)) == (0, 1), "Duplicates are fine: two_sum([3, 3], 6) should be (0, 1)."
assert two_sum([1, 2, 3], 100) is None, "When no pair adds up to target, return None."
assert two_sum([], 5) is None, "An empty list has no pair: return None."

class Num(int):
    ops = 0
    def _count(self, other, op):
        Num.ops += 1
        return op(int(self), int(other))
    def __add__(self, o): return self._count(o, int.__add__)
    def __radd__(self, o): return self._count(o, int.__add__)
    def __sub__(self, o): return self._count(o, int.__sub__)
    def __rsub__(self, o): return Num._count(Num(o), self, int.__sub__)
    __hash__ = int.__hash__

nums = [Num(v) for v in range(600)]
result = pair(two_sum(nums, Num(1197)))
assert result == (598, 599), "For 0..599 and target 1197 the answer is (598, 599). Got " + str(result)
assert Num.ops <= 5 * len(nums), "Your solution did " + format(Num.ops, ",") + " additions or subtractions for 600 numbers: that's O(n squared). Keep a dict of the numbers you have seen."

