PAIRS = {")": "(", "]": "[", "}": "{"}

def is_balanced(text: str) -> bool:
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
    return not stack

print(is_balanced("print(nums[0])"), is_balanced("([)]"))

slides.tests:
for text in ["()[]{}", "{[()]}", "print(len(nums[0]))", "", "no brackets at all"]:
    assert is_balanced(text) is True, "is_balanced(" + repr(text) + ") should be True."
for text in ["([)]", "(]", "((", "))((", "{'a': [1, 2}", ")"]:
    assert is_balanced(text) is False, "is_balanced(" + repr(text) + ") should be False."

