from collections import Counter

def first_unique(s: str) -> int:
    """Index of the first character that appears exactly once, or -1."""
    counts = Counter(s)
    for i, ch in enumerate(s):
        if counts[ch] == 1:
            return i
    return -1

cases = [("swiss", 1), ("kadak", 2), ("aabb", -1), ("", -1), ("z", 0)]
for given, expected in cases:
    got = first_unique(given)
    status = "PASS" if got == expected else "FAIL"
    print(f"{status}  first_unique({given!r}) = {got}, expected {expected}")
